def tokenize(text):
    out, i = [], 0
    while i < len(text):
        c = text[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            j = i
            while j < len(text) and text[j].isdigit():
                j += 1
            out.append(text[i:j]); i = j
        elif text[i:i+2] in ("<=", ">=", "==", "!="):
            out.append(text[i:i+2]); i += 2
        else:
            out.append(c); i += 1
    return out

